function Invoke-NSUnsetSSLCertKey {
    <#
    .SYNOPSIS
        Clears one or more NetScaler sslcertkey resource properties.
    .DESCRIPTION
        Configuration for certificate key resource.
    .PARAMETER CertKey
        Name for the certificate and private-key pair. Must begin with an ASCII alphanumeric or underscore (_) character, and must contain only ASCII alphanumeric, underscore, hash (#), period (.), space, colon (:), at (@), equals (=), and hyphen (-) characters. Cannot be changed after the certificate-key pair is created. The following requirement applies only to the Citrix ADC CLI: If the name includes one or more spaces, enclose the name in double or single quotation marks (for example, "my cert" or 'my cert'). Minimum length = 1
    .PARAMETER DeleteCertKeyFilesOnRemoval
        This option is used to automatically delete certificate/key files from physical device when the added certkey is removed. When deleteCertKeyFilesOnRemoval option is used at rm certkey command, it overwrites the deleteCertKeyFilesOnRemoval setting used at add/set certkey command. Default value: CERTKEYFILE_DELETE_NO Possible values = NO, ALWAYS, IF_EXPIRED
    .PARAMETER ExpiryMonItor
        Issue an alert when the certificate is about to expire. Possible values = ENABLED, DISABLED
    .PARAMETER Notificationperiod
        Time, in number of days, before certificate expiration, at which to generate an alert that the certificate is about to expire. Minimum value = 10 Maximum value = 100
    .PARAMETER Session
        The NetScaler session. If omitted, the current default session is used.
    .PARAMETER IgnoreNotFound
        Returns null instead of throwing for known NITRO not-found responses.
    .PARAMETER ReturnNullOnNotFound
        Returns null instead of throwing for known NITRO not-found responses.
    .PARAMETER ThrowOnWarning
        Treats NITRO warning responses as terminating errors.
    .PARAMETER PassThru
        Returns the updated resource after the operation completes.
    .EXAMPLE
        Invoke-NSUnsetSSLCertKey -CertKey 'example' -DeleteCertKeyFilesOnRemoval NO -PassThru
    .EXAMPLE
        Invoke-NSUnsetSSLCertKey -CertKey 'example' -DeleteCertKeyFilesOnRemoval NO -WhatIf
    .OUTPUTS
        System.Management.Automation.PSCustomObject
    .NOTES
        Generated from NetScaler NITRO API metadata.
        Generated: 2026-06-01 21:28
        Supported metadata versions: 13.1, 14.1.
    #>
    [CmdletBinding(SupportsShouldProcess)]
    param(
        [Parameter(Mandatory, Position = 0, ValueFromPipelineByPropertyName)]
        [string] $CertKey,

        [Parameter()]
        [ValidateSet('NO', 'ALWAYS', 'IF_EXPIRED')]
        [switch] $DeleteCertKeyFilesOnRemoval,

        [Parameter()]
        [ValidateSet('ENABLED', 'DISABLED')]
        [switch] $ExpiryMonItor,

        [Parameter()]
        [switch] $Notificationperiod,

        [Parameter()]
        [psobject] $Session = (Get-NSSession),

        [Parameter()]
        [switch] $IgnoreNotFound,

        [Parameter()]
        [switch] $ReturnNullOnNotFound,

        [Parameter()]
        [switch] $ThrowOnWarning,

        [Parameter()]
        [switch] $PassThru
    )

    process {
        $metadataVersion = Resolve-NSMetadataVersion -Session $Session -SupportedVersion @('13.1', '14.1')

        $transportParameters = @{}
        if ($PSBoundParameters.ContainsKey('IgnoreNotFound')) { $transportParameters.IgnoreNotFound = $IgnoreNotFound }
        if ($PSBoundParameters.ContainsKey('ReturnNullOnNotFound')) { $transportParameters.ReturnNullOnNotFound = $ReturnNullOnNotFound }
        if ($PSBoundParameters.ContainsKey('ThrowOnWarning')) { $transportParameters.ThrowOnWarning = $ThrowOnWarning }

        $body = @{ certkey = $CertKey }
        if ($PSBoundParameters.ContainsKey('DeleteCertKeyFilesOnRemoval')) { $body['deletecertkeyfilesonremoval'] = $true }
        if ($PSBoundParameters.ContainsKey('ExpiryMonItor')) { $body['expirymonitor'] = $true }
        if ($PSBoundParameters.ContainsKey('Notificationperiod')) { $body['notificationperiod'] = $true }

        if ($body.Count -le 1) {
            throw 'Specify at least one property switch to clear.'
        }

        if ($PSCmdlet.ShouldProcess("$CertKey", 'Clear sslcertkey properties')) {
            $response = Invoke-NSRestRequest @transportParameters -Session $Session -Method POST -Task config -Type sslcertkey -Action unset -Payload @{ sslcertkey = $body } -RawResponse

            if ($PassThru) {
                return Invoke-NSGetSSLCertKey -CertKey $CertKey -Session $Session
            }

            return $response
        }
    }
}
