        if ($PSBoundParameters.ContainsKey('Batchingdepth')) { $body['batchingdepth'] = $true }
        if ($PSBoundParameters.ContainsKey('Cache')) { $body['cache'] = $true }
        if ($PSBoundParameters.ContainsKey('CacheTimeout')) { $body['cachetimeout'] = $true }
        if ($PSBoundParameters.ContainsKey('HTTPMethod')) { $body['httpmethod'] = $true }
        if ($PSBoundParameters.ContainsKey('InsertClientCert')) { $body['insertclientcert'] = $true }
        if ($PSBoundParameters.ContainsKey('OCSPURLResolveTimeout')) { $body['ocspurlresolvetimeout'] = $true }
        if ($PSBoundParameters.ContainsKey('Producedattimeskew')) { $body['producedattimeskew'] = $true }
        if ($PSBoundParameters.ContainsKey('ResponderCert')) { $body['respondercert'] = $true }
        if ($PSBoundParameters.ContainsKey('ResponseTimeout')) { $body['resptimeout'] = $true }
        if ($PSBoundParameters.ContainsKey('SigningCert')) { $body['signingcert'] = $true }
        if ($PSBoundParameters.ContainsKey('TrustResponder')) { $body['trustresponder'] = $true }
        if ($PSBoundParameters.ContainsKey('Usenonce')) { $body['usenonce'] = $true }

