            return Invoke-NSGetSSLVServer -VServerName $VServerName -Session $Session
        }

        return $response
    }
}
# endregion Invoke-NSUpdateSSLVServer

# region Invoke-NSUpdateSSLZerotouchparam
function Invoke-NSUpdateSSLZerotouchparam {
    <#
    .SYNOPSIS
        Updates a NetScaler sslzerotouchparam resource.
    .DESCRIPTION
        Configuration for Zerotouch params resource.
    .PARAMETER OCSPBatchingdelay
        Maximum time, in milliseconds, to wait to accumulate OCSP requests to batch. Does not apply if the Batching Depth is 1. Minimum value = 1 Maximum value = 10000
    .PARAMETER OCSPBatchingdepth
        Number of certificates to batch together into one OCSP request. Batching avoids overloading the OCSP responder. A value of 1 signifies that each request is queried independently. For a value greater than 1, specify a timeout (batching delay) to avoid inordinately delaying the processing of a single certificate. Minimum value = 1 Maximum value = 8
    .PARAMETER OCSPCacheTimeout
        Timeout(in minutes) for caching the OCSP response. Default value: 1 Minimum value = 1 Maximum value = 43200
    .PARAMETER OCSPHTTPMethod
        HTTP method used to send ocsp request. POST is the default httpmethod. If request length is > 255, POST wil be used even if GET is set as httpMethod. Default value: POST Possible values = GET, POST
    .PARAMETER OCSPProducedattimeskew
        Time, in seconds, for which the Citrix ADC waits before considering the response as invalid. The response is considered invalid if the Produced At time stamp in the OCSP response exceeds or precedes the current Citrix ADC clock time by the amount of time specified. Default value: 300 Minimum value = 0 Maximum value = 86400
    .PARAMETER OCSPResponseTimeout
        Time, in milliseconds, to wait for an OCSP response. When this time elapses, an error message appears or the transaction is forwarded, depending on the settings on the virtual server. Includes Batching Delay time. Minimum value = 100 Maximum value = 120000
    .PARAMETER OCSPTrustResponder
        If trustResponder is set to YES, signature verification will be skipped for the OCSP response. Possible values = YES, NO
    .PARAMETER OCSPURLResolveTimeout
        Time, in milliseconds, to wait for an OCSP URL Resolution. When this time elapses, an error message appears or the transaction is forwarded, depending on the settings on the virtual server. Minimum value = 100 Maximum value = 2000
    .PARAMETER OCSPUsenonce
        Enable the OCSP nonce extension, which is designed to prevent replay attacks. Default value: ENABLED Possible values = ENABLED, DISABLED
    .PARAMETER Session
        The NetScaler session. If omitted, the current default session is used.
    .PARAMETER IgnoreNotFound
        Returns null instead of throwing for known NITRO not-found responses.
    .PARAMETER ReturnNullOnNotFound
        Returns null instead of throwing for known NITRO not-found responses.
    .PARAMETER ThrowOnWarning
        Treats NITRO warning responses as terminating errors.
    .PARAMETER PassThru
        Returns the updated resource after the operation completes.
    .EXAMPLE
        Invoke-NSUpdateSSLZerotouchparam  -PassThru
    .EXAMPLE
        Invoke-NSUpdateSSLZerotouchparam  -WhatIf
    .OUTPUTS
        System.Management.Automation.PSCustomObject
    .NOTES
        Generated from NetScaler NITRO API metadata.
        Generated: 2026-06-01 21:28
        Supported metadata versions: 13.1, 14.1.
    #>
    [CmdletBinding(SupportsShouldProcess)]
    param(
        [Parameter()]
        [int] $OCSPBatchingdelay,

        [Parameter()]
        [int] $OCSPBatchingdepth,

        [Parameter()]
        [int] $OCSPCacheTimeout,

        [Parameter()]
        [ValidateSet('GET', 'POST')]
        [string] $OCSPHTTPMethod,

        [Parameter()]
        [int] $OCSPProducedattimeskew,

        [Parameter()]
        [int] $OCSPResponseTimeout,

        [Parameter()]
        [ValidateSet('YES', 'NO')]
        [string] $OCSPTrustResponder,

        [Parameter()]
        [int] $OCSPURLResolveTimeout,

        [Parameter()]
        [ValidateSet('ENABLED', 'DISABLED')]
        [string] $OCSPUsenonce,

        [Parameter()]
        [psobject] $Session = (Get-NSSession),

        [Parameter()]
        [switch] $IgnoreNotFound,

        [Parameter()]
        [switch] $ReturnNullOnNotFound,

        [Parameter()]
        [switch] $ThrowOnWarning,

        [Parameter()]
        [switch] $PassThru
    )

    $metadataVersion = Resolve-NSMetadataVersion -Session $Session -SupportedVersion @('13.1', '14.1')

    $transportParameters = @{}
    if ($PSBoundParameters.ContainsKey('IgnoreNotFound')) { $transportParameters.IgnoreNotFound = $IgnoreNotFound }
    if ($PSBoundParameters.ContainsKey('ReturnNullOnNotFound')) { $transportParameters.ReturnNullOnNotFound = $ReturnNullOnNotFound }
    if ($PSBoundParameters.ContainsKey('ThrowOnWarning')) { $transportParameters.ThrowOnWarning = $ThrowOnWarning }

    $properties = [System.Collections.Generic.Dictionary[string, object]]::new([System.StringComparer]::Ordinal)
    if ($PSBoundParameters.ContainsKey('OCSPBatchingdelay')) { $properties['ocspbatchingdelay'] = $OCSPBatchingdelay }
    if ($PSBoundParameters.ContainsKey('OCSPBatchingdepth')) { $properties['ocspbatchingdepth'] = $OCSPBatchingdepth }
    if ($PSBoundParameters.ContainsKey('OCSPCacheTimeout')) { $properties['ocspcachetimeout'] = $OCSPCacheTimeout }
    if ($PSBoundParameters.ContainsKey('OCSPHTTPMethod')) { $properties['ocsphttpmethod'] = $OCSPHTTPMethod }
    if ($PSBoundParameters.ContainsKey('OCSPProducedattimeskew')) { $properties['ocspproducedattimeskew'] = $OCSPProducedattimeskew }
    if ($PSBoundParameters.ContainsKey('OCSPResponseTimeout')) { $properties['ocspresptimeout'] = $OCSPResponseTimeout }
    if ($PSBoundParameters.ContainsKey('OCSPTrustResponder')) { $properties['ocsptrustresponder'] = $OCSPTrustResponder }
    if ($PSBoundParameters.ContainsKey('OCSPURLResolveTimeout')) { $properties['ocspurlresolvetimeout'] = $OCSPURLResolveTimeout }
    if ($PSBoundParameters.ContainsKey('OCSPUsenonce')) { $properties['ocspusenonce'] = $OCSPUsenonce }

    $body = [System.Collections.Generic.Dictionary[string, object]]::new([System.StringComparer]::Ordinal)
    foreach ($key in $properties.Keys) {
        if ($null -ne $properties[$key] -and (-not ($properties[$key] -is [string]) -or $properties[$key] -ne '')) {
            $body[$key] = $properties[$key]
        }
    }

    if ($PSCmdlet.ShouldProcess('sslzerotouchparam', 'Update sslzerotouchparam')) {
        $response = Invoke-NSRestRequest @transportParameters -Session $Session -Method PUT -Task config -Type sslzerotouchparam -Payload @{ sslzerotouchparam = $body } -RawResponse

        return $response
    }
}
